(6931922, 1044382, 11769, '<td valign="top">Love it.</td>', 'Love it.', '2012-12-13 20:56:36.000000', NULL, 1),
(6931956, 1044205, 103142, '<td valign="top">Sure -- my husband as liquid nitrogen, and does he bring it out for a photo shoot? Not this time!! Well, there was that other time, and that other time, and even that other time... Oh well. Even if he did, my idea wasn''t as cool as this one... Nicely done!</td>', 'Sure -- my husband as liquid nitrogen, and does he bring it out for a photo shoot? Not this time!! Well, there was that other time, and that other time, and even that other time... Oh well. Even if he did, my idea wasn''t as cool as this one... Nicely done!', '2012-12-13 21:28:28.000000', NULL, 1),
