(6932024, 1044205, 67258, '<td valign="top">Very effective.</td>', 'Very effective.', '2012-12-13 23:29:56.000000', NULL, 1),
(6932026, 1044294, 97225, '<td valign="top">Lovely shot. I like the subdued colours.</td>', 'Lovely shot. I like the subdued colours.', '2012-12-13 23:34:10.000000', NULL, 1),
(6932027, 1043701, 97225, '<td valign="top">Beautiful minimalism. I love the colours.</td>', 'Beautiful minimalism. I love the colours.', '2012-12-13 23:35:05.000000', NULL, 1),
(6932028, 1044263, 97225, '<td valign="top">Great photo. I love the tones and the drama in the sky. Ribbon pick.</td>', 'Great photo. I love the tones and the drama in the sky. Ribbon pick.', '2012-12-13 23:36:13.000000', NULL, 1),
(6932030, 1044334, 97225, '<td valign="top">Nice symmetrical composition and beautiful colours.</td>', 'Nice symmetrical composition and beautiful colours.', '2012-12-13 23:37:08.000000', NULL, 1),
(6932031, 1044391, 97225, '<td valign="top">Lovely abstract.</td>', 'Lovely abstract.', '2012-12-13 23:37:20.000000', NULL, 1),
(6932033, 1044205, 97225, '<td valign="top">Interesting, informative and esthetically pleasing. Top 3.</td>', 'Interesting, informative and esthetically pleasing. Top 3.', '2012-12-13 23:40:17.000000', NULL, 1),
(6932034, 1044317, 97225, '<td valign="top">Very interesting element very elegantly photographed. Top 3</td>', 'Very interesting element very elegantly photographed. Top 3', '2012-12-13 23:41:15.000000', NULL, 1),
(6932036, 1044281, 94815, '<td valign="top">I love frame-filling symphonic stuff like this. The clash of themes, wheels as circles and ovals vs straight-lined spokes gives this a visual life not often achieved nor, sadly, even considered fashionable by some (clutter vs vibrance).</td>', 'I love frame-filling symphonic stuff like this. The clash of themes, wheels as circles and ovals vs straight-lined spokes gives this a visual life not often achieved nor, sadly, even considered fashionable by some (clutter vs vibrance).', '2012-12-13 23:42:40.000000', NULL, 1),
(6932037, 1043448, 94815, '<td valign="top">Rusty sunset works for me.</td>', 'Rusty sunset works for me.', '2012-12-13 23:43:08.000000', NULL, 1),
